-- mod-guild-level — the Customization objects and texts in each language (tools/decor/build_locales.py).
--
-- The objects' names are the housing's own (HouseDecor of retail).
-- Idempotent: every row is deleted before being written again.

DELETE FROM `item_template_locale` WHERE `ID` IN (SELECT `item` FROM `mod_guild_level_decor_item`);

DELETE FROM `gameobject_template_locale` WHERE `entry` IN (SELECT `entry` FROM `mod_guild_level_decor`);

DELETE FROM `module_string_locale` WHERE `module` = 'mod-guild-level' AND `id` BETWEEN 170 AND 179 AND `locale` IN ('deDE', 'esES', 'esMX', 'ruRU');
